# Stocks, Sauces and Soups (cusauce): lessons. Recipes live in Meal Prep (From the great kitchens; Make it from scratch).
ESC = Q("Indeed, stock is everything in cooking, at least in French cooking.", "A. Escoffier", "A Guide to Modern Cookery", "Chapter I, Fonds de Cuisine (London: Heinemann, 1907); public domain", "https://www.gutenberg.org/ebooks/71395")
LESSONS = {
"stocks": LES([
 P("A stock is a flavorful liquid made by simmering bones or vegetables with aromatics in water. It is the base of sauces, soups and braises."),
 ESC,
 K("<b>The parts:</b> bones (or vegetables), <b>mirepoix</b> (onion, carrot and celery, classically 2 parts onion to 1 carrot to 1 celery by weight), a <b>sachet</b> or bouquet garni (herbs and peppercorns), and <b>cold water</b>. <b>Kinds:</b> <b>white stock</b> (raw bones, pale), <b>brown stock</b> (bones and mirepoix roasted first, often with tomato paste), <b>fish fumet</b> (fish bones, quick) and <b>vegetable stock</b>."),
 TB(["Stock", "Typical simmering time"], [["Chicken (white)", "About 3 to 4 hours"], ["Beef or veal (white or brown)", "About 6 to 8 hours"], ["Fish (fumet)", "About 30 to 45 minutes"], ["Vegetable", "About 45 minutes to 1 hour"]], "Typical times from culinary school texts; bones vary"),
 LI("Start with cold water so proteins come out slowly and rise as scum you can skim.",
    "Bring up to a simmer and keep it there; don't boil.",
    "Skim often; don't stir.",
    "Strain through a fine strainer or chinois; cool by the two-stage rule; lift the fat off when cold."),
 W("Boiling churns fat and tiny bits into the liquid and clouds it. A gentle simmer keeps it clear. Bones with lots of connective tissue (knuckles, wings, feet) add gelatin, so a good stock sets like jelly when cold."),
 EX("Mirepoix by weight", "You need 1,200 g of mirepoix in the classic 2 : 1 : 1 ratio. How much onion?", ["4 parts in all; onion is 2 of them.", "$1200 \\times \\tfrac{2}{4} = 600$ g."], "600 g of onion (300 g each of carrot and celery)."),
 M("Salting stock. It will be reduced later, and salt concentrates; season the sauce or soup instead."),
 DRILL("Make a chicken stock from a roast chicken's carcass. Chill it overnight and see if it sets. Then make a second one with a few wings added and compare."),
 MP([("scratch/chicken-stock/", "Chicken stock", "the recipe"), ("scratch/beef-stock/", "Beef stock", "roasted bones"), ("scratch/vegetable-stock/", "Vegetable stock", "quick and meatless")]),
 TRY,
], "escoffier", "g_stock", "cia"),

"thickeners": LES([
 P("A sauce needs body to cling to food. Cooks thicken with starch, with egg yolks, or by reducing."),
 K("<b>Roux:</b> equal weights of fat (usually butter) and flour, cooked together. <b>White roux</b> cooks a few minutes without color (for béchamel); <b>blond</b> until golden (velouté); <b>brown</b> until nutty brown (espagnole). Darker roux has more flavor but less thickening power. <b>Slurry:</b> cornstarch or arrowroot stirred into cold liquid, then whisked into a simmering liquid. <b>Liaison:</b> egg yolks and cream, tempered with hot liquid and added at the end without boiling."),
 TB(["Roux per cup of liquid", "Result"], [["1 tablespoon each butter and flour", "Thin sauce or cream soup"], ["2 tablespoons each", "Medium sauce (classic béchamel)"], ["3 tablespoons each", "Thick sauce, as a binder for croquettes"]], "A common home-kitchen guide"),
 LI("Combine hot roux with cool liquid, or cool roux with hot liquid, whisking, to avoid lumps.",
    "Simmer a roux-thickened sauce for at least a few minutes, often 20 or more, to cook out the raw flour taste.",
    "A cornstarch slurry thickens as it comes to a boil; boiling it a long time or stirring hard can thin it again.",
    "Temper a liaison: whisk a little hot liquid into the yolks first, then whisk the mixture back in, and keep it below a simmer."),
 W("Starch granules swell with water as they heat and burst near a boil, thickening the liquid. Flour must be coated in fat (roux) or mixed in cold water first so the granules separate; dumped into hot liquid, the outside of each clump swells and seals the dry flour inside."),
 EX("Scale a roux", "A medium béchamel uses 2 tablespoons each of butter and flour per cup. How much of each for 6 cups?", ["$2 \\times 6 = 12$ tablespoons each, which is ¾ cup."], "12 tablespoons (¾ cup) of butter and 12 of flour."),
 M("Boiling a liaison. The yolks scramble into flecks."),
 DRILL("Make three small roux (white, blond, brown) and thicken one cup of milk or stock with each, using the same weight. Compare thickness and flavor."),
 MP([("recipes/bechamel-sauce/", "Béchamel Sauce", "a white roux at work")]),
 SCI([("/chemistry/chemistry/heating-curves/", "Heating curves", "how heat flows into a sauce")]),
 TRY,
], "g_stock", "cia"),

"mother-sauces": LES([
 P("In 1907 Escoffier organized French sauces around a few <b>leading sauces</b>, from which many others are made. Cooks today call five of them the <b>mother sauces</b>."),
 K("<b>The five mother sauces:</b> <b>béchamel</b> (milk thickened with white roux); <b>velouté</b> (white stock thickened with blond roux); <b>espagnole</b> or brown sauce (brown stock thickened with brown roux, with tomato and mirepoix); <b>tomato</b> (tomatoes cooked with aromatics, classically with stock and a roux); and <b>hollandaise</b> (butter emulsified into egg yolks with lemon or a vinegar reduction)."),
 V("cu-sauces", None, "Each mother is a liquid plus a way to thicken it. Open one to see its children and the Meal Prep recipe."),
 W("Learn the pattern, not five recipes: <b>liquid + thickener + flavor</b>. Change the liquid and you change the family. That is why a cook who knows the mothers can make hundreds of sauces."),
 Q("Brown sauce, or Espagnole.", "A. Escoffier", "A Guide to Modern Cookery", "Chapter II, The Leading Warm Sauces, No. 22 (1907); public domain", "https://www.gutenberg.org/ebooks/71395"),
 EX("Name the mother", "Chicken stock thickened with a blond roux.", ["White stock + blond roux."], "Velouté."),
 M("Thinking demi-glace is a mother sauce. In Escoffier's system it is espagnole reduced with brown stock, a step beyond the mother."),
 DRILL("Make béchamel one week and velouté the next, from the Meal Prep recipes. Taste them side by side: same roux, different liquid."),
 MP([("classics/", "From the Great Kitchens", "all five of Escoffier's sauces, adapted, with his originals quoted"), ("recipes/bechamel-sauce/", "Béchamel", ""), ("recipes/chicken-veloute/", "Chicken Velouté", ""), ("recipes/espagnole-demi-glace/", "Espagnole and Demi-Glace", ""), ("recipes/escoffier-tomato-sauce/", "Escoffier's Tomato Sauce", ""), ("recipes/hollandaise-sauce/", "Hollandaise", "")]),
 TRY,
], "escoffier", "g_sauces"),

"small-sauces": LES([
 P("A <b>small sauce</b> (also called a derivative or compound sauce) is a mother sauce with something added. Escoffier's book lists dozens."),
 K("<b>A few you should know:</b> from béchamel, <b>Mornay</b> (cheese) and <b>soubise</b> (onion purée); from velouté, <b>suprême</b> (chicken velouté with cream) and <b>allemande</b> (velouté thickened with yolks and cream); from espagnole/demi-glace, <b>bordelaise</b> (red wine and shallots), <b>chasseur</b> (mushrooms, shallots, white wine, tomato) and <b>Robert</b> (onion, white wine, mustard); from tomato, <b>Creole</b> and <b>Portuguese</b>; from hollandaise, <b>béarnaise</b> (tarragon and shallot reduction), <b>maltaise</b> (blood orange) and <b>mousseline</b> (whipped cream folded in)."),
 V("cu-sauces", {"open": "hollandaise"}, "Open each mother sauce to see its children."),
 W("To guess a small sauce's mother, ask what liquid or base it is built on. Cheese sauce on milk? Béchamel. Wine and shallots on brown stock? Espagnole. Tarragon in a butter emulsion? Hollandaise."),
 EX("Whose child?", "Béarnaise sauce.", ["It is a warm butter emulsion with yolks, flavored with a tarragon and shallot reduction."], "Hollandaise."),
 M("Thinking Mornay is a cheese soup. It's a béchamel with cheese (often Gruyère and Parmesan), thick enough to coat."),
 DRILL("Make béchamel, then split it: stir cheese into half for Mornay, and slowly cooked puréed onion into the other half for soubise."),
 MP([("recipes/eggs-benedict/", "Eggs Benedict", "hollandaise in action"), ("recipes/chicken-chasseur/", "Hunter's Chicken", "a chasseur sauce"), ("recipes/fish-bonne-femme/", "Fish Bonne Femme", "a velouté-style sauce with mushrooms")]),
 TRY,
], "escoffier", "g_sauces"),

"emulsions": LES([
 P("Oil and water don't mix, yet mayonnaise is thick and smooth. It's an emulsion: tiny drops of one liquid spread through another, held in place."),
 K("An <b>emulsion</b> has tiny drops of fat suspended in a water-based liquid (or the other way round). An <b>emulsifier</b> such as the lecithin in egg yolk, or mustard, coats the drops and keeps them apart. <b>Permanent:</b> mayonnaise, hollandaise. <b>Temporary:</b> a plain vinaigrette, which separates as it stands. <b>Beurre blanc</b> is butter whisked into a wine and shallot reduction."),
 LI("Add the fat slowly at first, drop by drop, then in a thin stream.",
    "Keep the temperature right: hollandaise and beurre blanc stay warm (too hot breaks them; too cold sets the butter).",
    "Vinaigrette: about 3 parts oil to 1 part acid, with salt and a little mustard to help it hold.",
    "A broken mayonnaise or hollandaise can often be saved: start with a fresh yolk (or a spoon of warm water) and whisk the broken sauce into it slowly."),
 W("A yolk can hold only so much oil at once. Pour fast, and the drops merge into an oily layer: the sauce <b>breaks</b>. Slow addition gives the emulsifier time to coat each new drop."),
 EX("Vinaigrette ratio", "You want 1 cup of vinaigrette at 3 : 1. How much oil and vinegar?", ["4 parts in all; 1 cup = 16 tablespoons.", "Oil: $\\tfrac34 \\times 16 = 12$ tablespoons; vinegar 4 tablespoons."], "¾ cup oil and ¼ cup vinegar."),
 SAFE("Uncooked egg yolk sauces (homemade mayonnaise) use raw eggs. The Food Code requires pasteurized eggs for such dishes when serving highly susceptible people, and many kitchens use pasteurized eggs for them always."),
 M("Letting hollandaise sit over boiling water. The yolks overheat and it splits. Keep it warm, not hot."),
 DRILL("Make mayonnaise by hand with a whisk. When it is thick, make a second batch and pour the oil fast on purpose; then rescue it with a new yolk."),
 MP([("scratch/mayonnaise/", "Mayonnaise", "the recipe"), ("scratch/vinaigrette/", "Italian-style vinaigrette", "a temporary emulsion"), ("recipes/hollandaise-sauce/", "Hollandaise Sauce", "Escoffier's version, adapted")]),
 TRY,
], "g_emulsion", "foodcode"),

"pan-sauces": LES([
 P("After you sear meat, the pan holds browned bits stuck to the bottom. Cooks call them <b>fond</b>, and they are the start of a quick sauce."),
 K("<b>A pan sauce:</b> pour off excess fat; sweat shallots; <b>deglaze</b> with wine, stock or juice, scraping up the fond; <b>reduce</b> by boiling until thicker and stronger; finish by swirling in cold butter off the heat (<b>monter au beurre</b>); season and serve. <b>Reduction</b> concentrates flavor because water boils away."),
 W("Reducing by half means half the volume is left, so everything that doesn't boil away (salt, acid, gelatin, sugar) is twice as concentrated. That's why you season at the end."),
 EX("Reduction", "You reduce 2 cups of stock by three-quarters. How much is left?", ["Three-quarters is gone; one-quarter remains.", "$2 \\times \\tfrac14 = \\tfrac12$ cup."], "½ cup."),
 EX("Salt concentrates", "A stock has 1 teaspoon of salt in 4 cups. You reduce it to 1 cup. How salty is it now, per cup?", ["The salt stays: 1 teaspoon in 1 cup instead of ¼ teaspoon per cup.", "Four times as salty."], "Four times as salty: 1 teaspoon per cup."),
 SAFE("Pour wine or spirits into the pan off the heat, away from the flame, then return it to the heat."),
 M("Letting the fond burn black. Burnt fond is bitter; deglaze while it is brown."),
 DRILL("Sear a pork chop or chicken breast. Rest it while you make a pan sauce with shallot, ½ cup stock, a splash of vinegar or wine, and a tablespoon of cold butter.", "Measure a cup of stock, reduce it by half, and taste it next to the original."),
 MP([("recipes/delmonico-steak/", "Delmonico Steak", "a steak with a butter finish"), ("recipes/chicken-chasseur/", "Hunter's Chicken", "a pan sauce with mushrooms and wine")]),
 TRY,
], "cia", "g_stock"),

"soups": LES([
 P("Soups use everything in this course: stocks, thickeners, purées and emulsions. Cooks group them by how they look."),
 K("<b>Clear soups:</b> broth (simmered meat), and <b>consommé</b>, a stock clarified with a \"raft\" of ground meat, egg whites and mirepoix that traps tiny particles. <b>Thick soups:</b> <b>cream soups</b> (thickened with roux or a liaison and finished with cream), <b>purées</b> (thickened by the vegetables or beans themselves, such as potato-leek or split pea), and <b>bisques</b> (shellfish soups, often thickened with rice). <b>Specialty and cold soups</b> include gazpacho and vichyssoise."),
 LI("Sweat aromatics gently; build flavor before the liquid.",
    "Purée soups smooth, then pass through a sieve for a restaurant finish.",
    "Season at the end, and taste hot (cold soups need more salt).",
    "Garnish to add texture: croutons, herb oil, a spoon of cream."),
 SAFE("Blend hot soup in small batches, no more than about half full, with the blender's vent open and covered with a towel, or use an immersion blender in the pot.", "Cool large batches of soup by the two-stage rule in shallow pans or an ice bath."),
 W("A purée is thick without flour because cooked starchy vegetables (potato, beans, squash) release their starch when blended. Too much blending of potato soup in a powerful blender can make it gluey, for the same reason as mashed potatoes."),
 EX("Name the soup", "Potatoes and leeks simmered in stock, then blended.", ["Thickened by the potatoes themselves."], "A purée soup (potage Parmentier)."),
 M("Boiling a cream soup after the cream or liaison goes in. It can curdle or scorch."),
 DRILL("Make potato-leek soup. Serve half hot as potage Parmentier, and chill the rest with cream for vichyssoise, tasting for salt when cold."),
 MP([("recipes/potage-parmentier/", "Potato and Leek Soup (Potage Parmentier)", "from Escoffier"), ("recipes/lobster-newberg/", "Lobster Newberg", "a rich cream sauce from Delmonico's, kin to a bisque")]),
 TRY,
], "escoffier", "g_stock", "cia"),
}
